def quicksort(C):
    n = len(C)
    if n > 1:
        pivot = choose_pivot(C) # define pivot
        p = partition(C, pivot) # define p
        C[:p+1] = quicksort(C[:p+1]) # right
        C[p+1:] = quicksort(C[p+1:]) # left
    return C

def choose_pivot(C):
    return C[(len(C) - 1) // 2]

def partition(C, pivot):
    i = 0
    j = len(C) - 1

    while True:
        while C[i] < pivot:
            i+=1
        while C[j] > pivot:
            j-=1
        if i >= j:
            return j
        C[i], C[j] = C[j], C[i] # change 
        i+=1
        j-=1

def merge_sort(C):
    n = len(C)
    if n <= 1:
        return C
    m = n // 2
    L = merge_sort(C[:m])
    R = merge_sort(C[m:])
    return merge(L, R)

def merge(L, R):
    C = []
    i = 0
    j = 0

    while i < len(L) and j < len(R):
        if L[i] <= R[j]:
            C.append(L[i])
            i+=1
        else:
            C.append(R[j])
            j+=1
    C.extend(L[i:])
    C.extend(R[j:])
    return C
